#!/usr/bin/env python3
"""AZ: certificates for Starostenko; standard library only. User-authorized 2026-11-08."""
from pathlib import Path
import re,json,html,os,socket,hashlib,base64,zlib,datetime,sys,tempfile
STANDARD='''AZ — стандарт дипломов и сертификатов специалистов. Утверждён пользователем 08.11.2026.
Эталон: /team/filatova-anna/ и /team/filatova-anna/certificates/.
В карточке специалиста после образования — компактная ссылка на отдельную страницу «Дипломы и сертификаты».
Отдельная страница на azmednsk.ru: карточки документов, две колонки на компьютере, одна на телефоне; название, точная подпись, превью без обрезки.
Нажатие открывает документ в модальном окне. Увеличить/Уместить, прокрутка, закрытие крестиком, Escape и по фону. Изображения правильно ориентированы. PDF имеет изображение для просмотра и ссылку на исходный PDF.
Сохранять ФИО, даты, квалификацию и формулировки документов; не придумывать образование. Сохранять роль специалиста, цены, запись, аналитику и остальной контент профиля.
Применять ко всем специалистам при добавлении документов. Массовое изменение других профилей этим пакетом не выполняется.
'''
ASSET_URL='/assets/starostenko-certificates-20261109/'
def one(pattern,repl,s):
 out,n=re.subn(pattern,lambda m:repl(m) if callable(repl) else repl,s,count=0,flags=re.S)
 assert n==1,f'STOP: template marker {pattern!r}: {n}'
 return out

def render(root,docs):
 template=(root/'team/filatova-anna/certificates/index.html').read_text()
 profile_path=Path('team/starostenko-vadim/index.html')
 profile=(root/profile_path).read_text()
 assert 'Старостенко' in profile and '202272' in profile,'STOP: wrong specialist profile'
 assert 'az-starostenko-certificates-link' not in profile,'STOP: package already installed'
 cards=[]; data={}
 for d in docs:
  key=d['key'];title=html.escape(d['title']);desc=html.escape(d['description']);src=ASSET_URL+key+'.jpg'
  data[key]=[d['title'],src]
  pdf=f'<p><a href="{ASSET_URL+key}.pdf" target="_blank" rel="noopener">Открыть оригинал PDF</a></p>' if d['pdf'] else ''
  cards.append(f'<article class="az-cert-item"><h2>{title}</h2><p>{desc}</p><button aria-label="Открыть документ: {title}" class="az-cert-thumb" data-cert="{key}" type="button"><img alt="Старостенко Вадим Анатольевич — {title}" loading="lazy" src="{src}"></button>{pdf}<button class="az-certificate" data-cert="{key}" type="button">Открыть документ</button></article>')
 heading='Дипломы и сертификаты Старостенко Вадима Анатольевича'
 section='<section class="container content-section az-cert-page"><h1>'+heading+'</h1><p>Старостенко Вадим Анатольевич — врач-остеопат клиники «Архитектура здоровья» в Новосибирске.</p><p>Документы об образовании, профессиональной переподготовке и повышении квалификации.</p><div class="az-cert-grid">'+''.join(cards)+'</div><p><a class="button" href="/team/starostenko-vadim/">О специалисте и запись на приём</a></p></section>'
 page=one(r'<section class="container content-section az-cert-page">.*?</section>',section,template)
 page=page.replace('filatova-anna','starostenko-vadim').replace('1316218','202272')
 page=page.replace('Филатова Анна Дмитриевна','Старостенко Вадим Анатольевич').replace('Филатовой Анны Дмитриевны','Старостенко Вадима Анатольевича')
 page=one(r'<title>.*?</title>','<title>'+heading+' | Новосибирск</title>',page)
 # Regenerate metadata, never retain reference specialist qualifications.
 page=re.sub(r'<meta\b[^>]*(?:name="description"|property="og:(?:title|description)")[^>]*>','',page)
 page=re.sub(r'<script\b[^>]*type="application/ld\+json"[^>]*>.*?</script>','',page,flags=re.S)
 meta='<meta name="description" content="'+heading+'. Образование и профессиональное обучение специалиста клиники «Архитектура здоровья», Новосибирск."><meta property="og:title" content="'+heading+'">'
 schema={'@context':'https://schema.org','@type':'WebPage','name':heading,'url':'https://azmednsk.ru/team/starostenko-vadim/certificates/','inLanguage':'ru-RU'}
 page=page.replace('</head>',meta+'<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False)+'</script></head>')
 page=one(r'const data=\{.*?\};let previousOverflow=', 'const data='+json.dumps(data,ensure_ascii=False)+';let previousOverflow=',page)
 page=page.replace("im.alt='Сертификат Старостенко Вадима Анатольевича: '","im.alt='Документ Старостенко Вадима Анатольевича: '")
 link='<div class="az-certificates" id="az-starostenko-certificates-link"><a class="az-certificate" href="/team/starostenko-vadim/certificates/">Дипломы и сертификаты<span>Образование и профессиональное обучение Старостенко Вадима Анатольевича →</span></a></div>'
 profile=one(r'(</dl>)(<div class="az-profile-price">)',lambda m:m[1]+link+m[2],profile)
 styles=re.search(r'\.az-certificates\{.*?(?=\.az-filatova-price)',template,re.S)
 assert styles,'STOP: reference certificate styles missing'
 profile=profile.replace('</head>','<style id="az-starostenko-certificates-style">'+styles[0]+'</style></head>')
 assert len(re.findall(r'<article class="az-cert-item">',page))==3
 assert 'eurokappa' not in page.lower() and 'ormco' not in page.lower() and 'Филатов' not in page
 assert profile.count('data-az-doctor-booking=')==(root/profile_path).read_text().count('data-az-doctor-booking=')
 result={str(profile_path):profile.encode(),'team/starostenko-vadim/certificates/index.html':page.encode()}
 sitemap=root/'sitemap.xml';url='https://azmednsk.ru/team/starostenko-vadim/certificates/'
 if sitemap.exists():
  sm=sitemap.read_text(); assert '</urlset>' in sm
  if url not in sm:result['sitemap.xml']=sm.replace('</urlset>','<url><loc>'+url+'</loc></url></urlset>').encode()
 return result

def run():
 payload=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
 docs=payload['documents']; assets={k:base64.b64decode(v) for k,v in payload['assets'].items()}
 dry=len(sys.argv)==3 and sys.argv[1]=='--check-root'
 root=Path(sys.argv[2]) if dry else Path('/var/www/azmednsk-preview')
 if not dry:
  assert len(sys.argv)==1,'STOP: unexpected arguments'
  assert socket.gethostname()=='vdska' and os.geteuid()==0,'STOP: run as root on vdska'
  config=Path('/etc/nginx/sites-available/azmednsk-preview').read_text()
  assert re.search(r'server_name\s+[^;]*\bazmednsk\.ru\b',config),'STOP: server_name'
  assert set(re.findall(r'^\s*root\s+([^;]+);',config,re.M))=={str(root)},'STOP: document root'
  assert root.is_dir() and not root.is_symlink(),'STOP: root'
 changes=render(root,docs)
 for name,blob in assets.items():changes[ASSET_URL.strip('/')+'/'+name]=blob
 for rel,blob in changes.items():
  p=root/rel
  assert not any(x.is_symlink() for x in [p,*p.parents]),'STOP: symlink '+str(p)
  if rel not in ('team/starostenko-vadim/index.html','sitemap.xml'):assert not p.exists(),'STOP: new target exists '+rel
 print('PREFLIGHT=PASS; DOCUMENTS=3; ASSETS='+str(len(assets)))
 if dry:
  preview=Path(__file__).parent/'preview';preview.mkdir(exist_ok=True)
  for rel,blob in changes.items():p=preview/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(blob)
  print('CHECK_ONLY=PASS; LIVE_WRITES=NONE');return
 backup=Path('/var/backups/azmednsk')/('starostenko-certificates-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
 backup.mkdir(parents=True,exist_ok=False)
 old={rel:(root/rel).read_bytes() if (root/rel).exists() else None for rel in changes}
 for rel,blob in old.items():
  if blob is not None:p=backup/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(blob)
 (backup/'new-files.json').write_text(json.dumps([k for k,v in old.items() if v is None]))
 (backup/'STANDARD.txt').write_text(STANDARD)
 written=[]
 try:
  # Assets and gallery first, then profile and sitemap.
  for rel in sorted(changes,key=lambda x:x in ('team/starostenko-vadim/index.html','sitemap.xml')):
   p=root/rel;p.parent.mkdir(parents=True,exist_ok=True)
   fd,tmp=tempfile.mkstemp(prefix='.az-cert-',dir=p.parent)
   try:
    with os.fdopen(fd,'wb') as f:f.write(changes[rel])
    os.chmod(tmp,0o644);os.replace(tmp,p);written.append(rel)
   finally:
    if os.path.exists(tmp):os.unlink(tmp)
  for rel,blob in changes.items():assert (root/rel).read_bytes()==blob
 except BaseException:
  for rel in reversed(written):
   p=root/rel
   if old[rel] is None:p.unlink()
   else:p.write_bytes(old[rel])
  raise
 standard=Path('/var/lib/azmednsk/standards');standard.mkdir(parents=True,exist_ok=True)
 if not (standard/'specialist-certificates-20261108.txt').exists(): (standard/'specialist-certificates-20261108.txt').write_text(STANDARD)
 print('STAROSTENKO_CERTIFICATES=PASS; DOCUMENTS=3; STANDARD=SAVED')
 print('BACKUP='+str(backup))
 print('URL=https://azmednsk.ru/team/starostenko-vadim/certificates/')
 print('Send this output for external verification.')


PAYLOAD=''
if __name__=='__main__':run()
